import shutil
import openpyxl
from openpyxl.styles import PatternFill

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

if "Before" in wb.sheetnames:
    wb.active = wb["Before"]
if "Sheet3" in wb.sheetnames:
    del wb["Sheet3"]

ws_vals = vals["Before"]
ws = wb["Before"]

items = []
for r in range(1, 17):
    v = ws_vals.cell(row=r, column=1).value
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        items.append((r, float(v)))

n = len(items)
low = 994108.0
high = 994112.0
mid = (low + high) / 2.0

best_sum = None
best_mask = None

for mask in range(1, 1 << n):
    s = 0.0
    for i, (_, v) in enumerate(items):
        if mask & (1 << i):
            s += v
    if low - 1e-6 <= s <= high + 1e-6:
        if best_sum is None or abs(s - mid) < abs(best_sum - mid) - 1e-12:
            best_sum = s
            best_mask = mask

green = PatternFill(fill_type="solid", start_color="FF00FF00", end_color="FF00FF00")
no_fill = PatternFill(fill_type=None)

for r in range(1, 17):
    ws.cell(row=r, column=1).fill = no_fill

if best_mask is not None:
    for i, (r, _) in enumerate(items):
        if best_mask & (1 << i):
            ws.cell(row=r, column=1).fill = green
    ws["C2"] = round(float(best_sum), 2)
else:
    ws["C2"] = None

print("items:", n)
print("best_sum:", best_sum)
print("best_mask:", best_mask)
if best_mask is not None:
    print("highlighted rows:", [r for i, (r, _) in enumerate(items) if best_mask & (1 << i)])

wb.save(OUT)
